const body = $input.first().json.body ?? $input.first().json;
const { campaign_id, campaign_name, artist_id, campaign_type, created_by } = body;

console.log('[DATIAM:campaign] campaign.created —', campaign_id, campaign_name);

// ─────────────────────────────────────────────────────────────────────────
// TODO: Add Slack notification node after this to send to #campaigns channel
// Slack message format:
//   *New Campaign Created* :rocket:
//   *Name:* {{campaign_name}}
//   *Type:* {{campaign_type}}
//   *ID:* {{campaign_id}}
// ─────────────────────────────────────────────────────────────────────────

return [{
  json: {
    handled: true,
    event: 'campaign.created',
    campaign_id,
    campaign_name,
    artist_id,
    campaign_type,
    created_by,
    processed_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body ?? $input.first().json;
const { campaign_id, campaign_name, from_stage, to_stage, artist_id, changed_by } = body;

console.log('[DATIAM:campaign] campaign.stage.changed —', campaign_id, from_stage, '->', to_stage);

// ─────────────────────────────────────────────────────────────────────────
// TODO: Add Slack notification node to alert the team about stage progression
// Slack message format:
//   *Campaign Stage Updated* :bar_chart:
//   *Campaign:* {{campaign_name}}
//   *Progress:* {{from_stage}} → {{to_stage}}
// ─────────────────────────────────────────────────────────────────────────

return [{
  json: {
    handled: true,
    event: 'campaign.stage.changed',
    campaign_id,
    campaign_name,
    from_stage,
    to_stage,
    artist_id,
    changed_by,
    processed_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body ?? $input.first().json;
const { campaign_id, campaign_name, artist_id, final_kpis } = body;

console.log('[DATIAM:campaign] campaign.completed —', campaign_id, campaign_name);

return [{
  json: {
    campaign_id,
    campaign_name,
    artist_id,
    final_kpis: final_kpis ?? null
  }
}];

const body = $input.first().json.body ?? $input.first().json;
console.log('[DATIAM:campaign] Unknown event — ignoring:', JSON.stringify(body));
return [{ json: { handled: false } }];

const input = $input.first().json;
console.log('[DATIAM:campaign] Completed:', JSON.stringify(input));
return [{ json: input }];
